//       const res = await apiGet(`/trucks?status=ARCHIVED&search=${encodeURIComponent(search)}&page=${p}&pageSize=${ARCHIVES_PAGE_SIZE_A4}`);
//       setArchivedTrucks(res.data);
//       setTotal(res.total);
//       setTotalPages(res.totalPages);
//     } catch (e) { showApiError(e); }
//   }, []);

//   useEffect(() => { fetchArchived(page, searchQuery); }, [page, fetchArchived]);
